def split_array(nums, k):
    def best(i, parts):
        if parts == 1:
            return sum(nums[i:])
        result, total = float("inf"), 0
        for j in range(i, len(nums) - parts + 1):
            total += nums[j]
            result = min(result, max(total, best(j + 1, parts - 1)))
        return result
    return best(0, k)

def split_array(nums, k):
    from functools import cache
    P = [0]
    for x in nums:
        P.append(P[-1] + x)
    n = len(nums)

    @cache
    def best(i, parts):
        if parts == 1:
            return P[n] - P[i]
        return min(max(P[j + 1] - P[i], best(j + 1, parts - 1))
                   for j in range(i, n - parts + 1))

    return best(0, k)

def split_array(nums, k):
    def parts_needed(cap):
        parts, total = 1, 0
        for x in nums:
            if total + x > cap:
                parts, total = parts + 1, 0
            total += x
        return parts

    lo, hi = max(nums), sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if parts_needed(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
